insert into public.biblioteca (tipo, titulo, autor, tribunal, sala, fecha, anio, jurisdiccion, fuero, publicacion, articulos, temas, resultado, sumario, sumario_oficial, url, acceso, verificado_el, origen, clave) values
('doctrina', 'El daño moral en el Código Civil y Comercial de la Nación', 'Ingrid Wilhelm (dir. Elisa Romano)', null, null, null, 2023, null, null, 'Tesis de Maestría en Derecho Civil Patrimonial, Pontificia Universidad Católica Argentina', null, array['daño moral']::text[], null, 'Analiza el daño extrapatrimonial en el CCyC: concepto, legitimación y métodos de cuantificación, con derecho comparado. Marco general para fundar el art. 1741.', false, 'https://repositorio.uca.edu.ar/handle/123456789/17883', 'abierto', null, 'relevamiento', '4cb7a33ed516876da742794b45edf336'),
('doctrina', 'La cuantificación del daño extrapatrimonial y el cómputo de intereses', 'Facundo Martínez Paz', null, null, null, 2019, null, null, 'Pensamiento Civil (revista digital)', null, array['daño moral', 'intereses']::text[], null, 'Propone tratar el daño moral como deuda de valor, con tasa pura hasta la cuantificación y una tasa que compense la inflación después. Útil para discutir intereses sobre el daño moral.', false, 'https://pensamientocivil.com.ar/doctrina/4248-cuantificacion-del-dano-extrapatrimonial-y-computo-intereses', 'abierto', null, 'relevamiento', '93c59c24d1085cbdf6b75dd9f5ec42d6'),
('doctrina', 'Desde San Luis: cuantificación y actualización monetaria', 'Gabriel M. Leonhardt', null, null, null, 2018, null, null, 'Pensamiento Civil (revista digital)', null, array['daño moral', 'intereses']::text[], null, 'Examina cómo la inflación afecta la cuantificación del daño moral y qué tasa corresponde según se fije a valores históricos o actuales. Complementa el debate sobre tasa pura.', false, 'https://pensamientocivil.com.ar/doctrina/3873-san-luis-cuantificacion-y-actualizacion-monetaria', 'abierto', null, 'relevamiento', '4feedc7dd08559108ef963a8996333be'),
('doctrina', 'Anatocismo e intereses', 'Carlos Alberto Parellada, Silvina Furlotti, Pablo Quirós y Claudio Leiva', null, null, null, 2017, null, null, 'XXVI Jornadas Nacionales de Derecho Civil (La Plata, 2017), SEDICI-UNLP', null, array['intereses']::text[], null, 'Ponencia sobre la naturaleza y el régimen de los intereses compensatorios, moratorios y punitorios en el CCyC, incluido el anatocismo del art. 770.', false, 'https://sedici.unlp.edu.ar/handle/10915/80037', 'abierto', null, 'relevamiento', '5d9fd10cc7ce07c92fbce8a965fc3145'),
('doctrina', 'Límite de cobertura en el seguro obligatorio automotor. Actualidad en el fuero nacional en lo civil', 'Ignacio María Díaz Gamba (dir. María Fabiana Compiani)', null, null, null, 2025, null, null, 'Tesis de maestría, Pontificia Universidad Católica Argentina', null, array['suma asegurada', 'citación en garantía']::text[], null, 'Estudia la inoponibilidad del límite de cobertura del seguro obligatorio y sistematiza los criterios de las salas de la Cámara Civil. Muy útil para elegir argumentos según la sala.', false, 'https://repositorio.uca.edu.ar/handle/123456789/22301', 'abierto', null, 'relevamiento', '2d1beb0cb4fd75778144abbd3520bb44'),
('doctrina', 'Los límites cuantitativos del seguro en los fallos de la Corte Suprema de Justicia de la Nación, la doctrina de la arbitrariedad y el sistema republicano de gobierno', 'Daniel Guffanti', null, null, null, 2024, null, null, 'El Derecho, Suplemento Especial "Novedades en el Derecho de Seguros", n.º 15.743 (repositorio UCA)', null, array['suma asegurada', 'franquicia']::text[], null, 'Revisa cómo trató la CSJN los límites de cobertura y franquicias y las tensiones con la arbitrariedad de sentencia. Sirve para anticipar la respuesta de la Corte.', false, 'https://repositorio.uca.edu.ar/handle/123456789/18176', 'abierto', null, 'relevamiento', '20c666085e4305e0da77ea6fb9e27a0e'),
('doctrina', 'La valoración judicial del límite de cobertura en el contrato de seguro', 'Henoch Romero Boue', null, null, null, 2026, null, null, 'Diálogos y Voces Judiciales, vol. 4, n.º 1 (Poder Judicial de Jujuy)', null, array['suma asegurada']::text[], null, 'Sostiene que aplicar el límite en forma nominal, aun con intereses, puede dar resultados irrazonables con inflación persistente, y propone un control judicial de razonabilidad.', false, 'https://dialogos.justiciajujuy.gov.ar/index.php/dvj/es/article/view/46', 'abierto', null, 'relevamiento', '93545f8746ba5b9fb568c466b0392bf2'),
('doctrina', 'La actualización monetaria de las sumas aseguradas', 'Waldo Augusto Sobrino', null, null, null, 2017, null, null, 'SAIJ Doctrina (DACF180147)', null, array['suma asegurada']::text[], null, 'Defiende la actualización de las sumas aseguradas frente a la inflación. Primer trabajo de una serie del autor sobre el tema.', false, 'https://www.saij.gob.ar/waldo-augusto-sobrino-actualizacion-monetaria-sumas-aseguradas-dacf180147-2017-11-08/123456789-0abc-defg7410-81fcanirtcod', 'abierto', null, 'relevamiento', 'd2a5cbfd7cb095ad1ac12ac86777ac51'),
('doctrina', 'Obligatoriedad de la actualización monetaria de las sumas aseguradas (en la Provincia de Buenos Aires y otros argumentos legales que la fundamentan)', 'Waldo Augusto Sobrino', null, null, null, 2024, null, null, 'SAIJ Doctrina (DACF240092)', null, array['suma asegurada']::text[], null, 'Sostiene que en PBA la actualización de la suma asegurada es obligatoria, con apoyo en la doctrina de la SCBA, y suma otros fundamentos legales. Útil para litigar en provincia.', false, 'https://www.saij.gob.ar/waldo-augusto-sobrino-obligatoriedad-actualizacion-monetaria-sumas-aseguradas-provincia-buenos-aires-otros-argumentos-legales-fundamentan-dacf240092-2024-10-14/123456789-0abc-defg2900-42fcanirtcod', 'abierto', null, 'relevamiento', 'cd9089b5ea7442f4064f812073617aeb'),
('doctrina', 'El fallo "Flores" de la Corte Suprema de Justicia: su inaplicabilidad con la vigencia del Código Civil y Comercial', 'Waldo Augusto Sobrino', null, null, null, 2017, null, null, 'SAIJ Doctrina (DACF180148)', null, array['franquicia', 'suma asegurada']::text[], null, 'Critica la doctrina de la CSJN en "Flores" sobre la oponibilidad del límite y sostiene que no se aplica tras el CCyC. Argumento para pedir apartarse del precedente.', false, 'https://www.saij.gob.ar/waldo-augusto-sobrino-fallo-flores-corte-suprema-justicia-su-inaplicabilidad-vigencia-codigo-civil-comercial-dacf180148-2017-08-31/123456789-0abc-defg8410-81fcanirtcod', 'abierto', null, 'relevamiento', '2b5e9df716703a6f41ef3aa7abcfbb35'),
('doctrina', 'Fallo "Flores": cada día se marchita más. Los argumentos sustanciales de la propia Corte Suprema de Justicia de la Nación para no aplicar el fallo "Flores"', 'Waldo Augusto Sobrino', null, null, null, 2024, null, null, 'SAIJ Doctrina (DACF240091)', null, array['franquicia', 'suma asegurada']::text[], null, 'Reúne argumentos, incluidos fallos de la propia CSJN, para que los tribunales no apliquen "Flores". Útil para fundar la inoponibilidad o actualización del límite.', false, 'https://www.saij.gob.ar/waldo-augusto-sobrino-fallo-flores-cada-dia-se-marchita-mas-argumentos-sustanciales-propia-corte-suprema-justicia-nacion-para-aplicar-fallo-flores-parte-todos-tribunales-pais-segun-leading-case-oliva-vs-coma-29-febrero-2024-dacf240091-2024-08-30/123456789-0abc-defg1900-42fcanirtcod', 'abierto', null, 'relevamiento', '5efc3d325896a5de0c55e942ac3ef843'),
('norma', 'Código Civil y Comercial de la Nación (Ley 26.994)', null, null, null, null, null, null, null, null, '1744', array['privación de uso']::text[], null, 'Quien invoca un daño debe probarlo, salvo que la ley lo presuma o que surja notorio de los hechos. Es el punto de apoyo para sostener que la privación de uso es un daño notorio que no requiere prueba del gasto.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/235000-239999/235975/texact.htm', null, null, 'relevamiento', '411a8f6ad3b1b9269a4037c701a6356f'),
('norma', 'Código Civil y Comercial de la Nación (Ley 26.994)', null, null, null, null, null, null, null, null, '1737, 1739 y 1744', array['desvalorización']::text[], null, 'Define el daño resarcible y exige que el perjuicio sea cierto y subsistente; la desvalorización venal debe acreditarse (en la práctica, por pericia) salvo que surja notoria de los hechos.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/235000-239999/235975/texact.htm', null, null, 'relevamiento', '97f9a774f419c4c130642dd6757d17e5'),
('norma', 'Código Civil y Comercial de la Nación (Ley 26.994)', null, null, null, null, null, null, null, null, '1738 y 1740', array['daño emergente']::text[], null, 'La indemnización comprende la pérdida o disminución del patrimonio (daño emergente), el lucro cesante y la chance; la reparación debe ser plena y el damnificado puede optar por el reintegro específico.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/235000-239999/235975/texact.htm', null, null, 'relevamiento', '019d3341a851d4bb5eda0f34de8289b2'),
('norma', 'Código Civil y Comercial de la Nación (Ley 26.994)', null, null, null, null, null, null, null, null, '1746', array['incapacidad']::text[], null, 'En lesiones o incapacidad permanente, la indemnización se calcula como un capital cuyas rentas cubran la merma de aptitud para actividades productivas o económicamente valorables y se agote al fin de la vida útil; base legal de las fórmulas matemáticas.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/235000-239999/235975/texact.htm', null, null, 'relevamiento', '0cb71061d32f4e56ef66c9c9a1ec1b3f'),
('norma', 'Código Civil y Comercial de la Nación (Ley 26.994)', null, null, null, null, null, null, null, null, '1741', array['daño moral']::text[], null, 'Regula la legitimación para reclamar las consecuencias no patrimoniales y manda fijar el monto ponderando las satisfacciones sustitutivas y compensatorias que pueden procurar las sumas reconocidas.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/235000-239999/235975/texact.htm', null, null, 'relevamiento', '4aea103390f35a844e3024c812d209e5'),
('norma', 'Ley Nacional de Tránsito 24.449', null, null, null, null, null, null, null, null, '41', array['concurrencia']::text[], null, 'En las encrucijadas se debe ceder siempre el paso a quien cruza desde la derecha; esa prioridad es absoluta y solo se pierde en los supuestos que la norma enumera.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/0-4999/818/texact.htm', null, null, 'relevamiento', 'd45a0a7ea77815cb5fb8d4ba1c1af1c9'),
('norma', 'Ley Nacional de Tránsito 24.449', null, null, null, null, null, null, null, null, '64', array['concurrencia']::text[], null, 'Define el accidente de tránsito y presume responsable a quien carecía de prioridad de paso o cometió una infracción vinculada con la causa del hecho.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/0-4999/818/texact.htm', null, null, 'relevamiento', 'fb60fa7bf2ff61a32fc2673db3d2f341'),
('norma', 'Código Civil y Comercial de la Nación (Ley 26.994)', null, null, null, null, null, null, null, null, '1757 y 1769', array['concurrencia']::text[], null, 'Responsabilidad objetiva por el riesgo o vicio de las cosas, aplicable a los daños causados por la circulación de vehículos. Es el marco en que se discute la concurrencia de culpas como eximente parcial.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/235000-239999/235975/texact.htm', null, null, 'relevamiento', '3061fe69d19c650281c693c41a4e3418'),
('norma', 'Ley 13.927 de la Provincia de Buenos Aires (Código de Tránsito)', null, null, null, null, null, null, null, null, '1', array['concurrencia']::text[], null, 'La Provincia adhiere a las Leyes nacionales 24.449 y 26.363 en cuanto no se opongan a la ley provincial; por eso el art. 41 de la Ley 24.449 rige en PBA.', false, 'https://normas.gba.gob.ar/ar-b/ley/2008/13927/2954', null, null, 'relevamiento', 'c503ccb36c94350dac0df9620397d054'),
('norma', 'Ley de Seguros 17.418', null, null, null, null, null, null, null, null, '109', array['citación en garantía']::text[], null, 'En el seguro de responsabilidad civil, el asegurador se obliga a mantener indemne al asegurado por lo que deba a un tercero por un hecho ocurrido durante la vigencia.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/35000-39999/39520/texact.htm', null, null, 'relevamiento', '2f90a18965c9f78ef11c6a131f9751a8'),
('norma', 'Ley de Seguros 17.418', null, null, null, null, null, null, null, null, '118', array['citación en garantía']::text[], null, 'El damnificado tiene privilegio sobre la suma asegurada y puede citar en garantía al asegurador hasta que la causa se abra a prueba, demandando ante el juez del lugar del hecho o del domicilio del asegurador; la sentencia hace cosa juzgada respecto de él.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/35000-39999/39520/texact.htm', null, null, 'relevamiento', '29b7339b4171badc75e551e958b1dd66'),
('norma', 'Ley de Seguros 17.418', null, null, null, null, null, null, null, null, '118 (párrafo tercero)', array['franquicia']::text[], null, 'La condena contra el asegurador se ejecuta en la medida del seguro y no puede oponer las defensas nacidas después del siniestro; es la base del debate sobre la oponibilidad de franquicias y límites de cobertura.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/35000-39999/39520/texact.htm', null, null, 'relevamiento', '309577c727e7b37f140bc61031b53606'),
('norma', 'Ley Nacional de Tránsito 24.449', null, null, null, null, null, null, null, null, '68', array['citación en garantía']::text[], null, 'Todo automotor debe tener seguro obligatorio que cubra los daños a terceros, transportados o no, según las condiciones que fije la autoridad aseguradora.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/0-4999/818/texact.htm', null, null, 'relevamiento', '2831ceeb5edac6c986c30cc2985553e6'),
('norma', 'Código Civil y Comercial de la Nación (Ley 26.994)', null, null, null, null, null, null, null, null, '768, 770 y 772', array['intereses']::text[], null, 'Intereses moratorios desde la mora (art. 768), excepciones al anatocismo, entre ellas la demanda judicial (art. 770 inc. b), y deudas de valor referidas al valor real al momento que corresponda evaluar la deuda, que una vez cuantificadas pasan a regirse por las reglas de las obligaciones dinerarias (art. 772).', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/235000-239999/235975/texact.htm', null, null, 'relevamiento', 'f4fd56a347bd12c4546740accdbccbb2'),
('norma', 'Código Civil y Comercial de la Nación (Ley 26.994)', null, null, null, null, null, null, null, null, '2561 (tercer párrafo)', array['prescripción']::text[], null, 'El reclamo de la indemnización por responsabilidad civil prescribe a los tres años; es el plazo para la acción del tercero damnificado contra el responsable y su aseguradora citada.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/235000-239999/235975/texact.htm', null, null, 'relevamiento', 'b6c2ff22d4793f48eec82c9406896b39'),
('norma', 'Ley de Seguros 17.418', null, null, null, null, null, null, null, null, '58', array['prescripción']::text[], null, 'Las acciones fundadas en el contrato de seguro prescriben al año desde que la obligación es exigible; alcanza los reclamos del asegurado contra su aseguradora, no la acción del tercero.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/35000-39999/39520/texact.htm', null, null, 'relevamiento', '1d1622ea224af2c71a3882c3d9afd065'),
('norma', 'Código Civil y Comercial de la Nación (Ley 26.994)', null, null, null, null, null, null, null, null, '1094, 2532 y 2560', array['prescripción']::text[], null, 'Normas que se invocan en el debate sobre el plazo para reclamar a la aseguradora en una relación de consumo: interpretación pro consumidor (1094), aplicación supletoria de las reglas de prescripción (2532) y plazo genérico de cinco años (2560).', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/235000-239999/235975/texact.htm', null, null, 'relevamiento', '91ca3b3f53fb30bfc924671964109a77'),
('norma', 'Ley 26.589 de Mediación y Conciliación (Nación y CABA)', null, null, null, null, null, null, null, null, '1, 2, 5, 18 y 35', array['mediación']::text[], null, 'Mediación previa obligatoria a todo proceso (1), acta del mediador como requisito para demandar (2), causas excluidas (5), suspensión de la prescripción (18) y honorario básico del mediador según la reglamentación (35).', false, 'https://servicios.infoleg.gob.ar/infolegInternet/anexos/165000-169999/166999/texact.htm', null, null, 'relevamiento', '2065ffec15795470a502e53779347bb6'),
('norma', 'Decreto 1467/2011 (reglamentario de la Ley 26.589)', null, null, null, null, null, null, null, null, 'Reglamentación completa (honorarios en unidades de honorarios de mediación)', array['mediación']::text[], null, 'Reglamenta la mediación prejudicial obligatoria en Nación, incluido el régimen de honorarios del mediador expresados en unidades de honorarios de mediación.', false, 'https://servicios.infoleg.gob.ar/infolegInternet/verNorma.do?id=187495', null, null, 'relevamiento', '3c4121b46e9755380a126bcdb2d3f7f6'),
('norma', 'Ley 13.951 de la Provincia de Buenos Aires (Mediación)', null, null, null, null, null, null, null, null, '2 y 31', array['mediación']::text[], null, 'Establece la mediación obligatoria previa a todo juicio en PBA, con las exclusiones del art. 4 (art. 2), y fija que el mediador percibe una suma fija reglamentaria, a cargo de las partes según el acuerdo, con previsiones para cobrarla si la mediación fracasa (art. 31).', false, 'https://normas.gba.gob.ar/ar-b/ley/2009/13951/2909', null, null, 'relevamiento', '5ef70aa4ae05e8d7c9d02f410a7a7582'),
('norma', 'Resolución SSN 589/2025 (RESOL-2025-589-APN-SSN#MEC)', null, null, null, null, null, null, null, null, '4, 5, 8 y 11', array['suma asegurada']::text[], null, 'Fija los límites vigentes para pólizas emitidas o renovadas desde el 1/1/2026: en el seguro obligatorio (SO-RC), $20.800.000 por muerte o incapacidad total y permanente por persona y $910.000 de gastos sanatoriales; en el seguro voluntario de RC, $208.000.000 por acontecimiento para autos, camionetas y motos.', false, 'https://www.boletinoficial.gob.ar/detalleAviso/primera/333893/20251103', null, null, 'relevamiento', 'b19d3d73bd477d61c17b72bbdfd4b8a2'),
('norma', 'Resolución SSN 589/2025 (RESOL-2025-589-APN-SSN#MEC)', null, null, null, null, null, null, null, null, '1 y 3', array['franquicia']::text[], null, 'Para el seguro de RC del transporte público de pasajeros fija un límite de $676.000.000 por acontecimiento y un descubierto obligatorio a cargo del asegurado de $3.380.000 por acontecimiento.', false, 'https://www.boletinoficial.gob.ar/detalleAviso/primera/333893/20251103', null, null, 'relevamiento', '042c184388d2d5808e2e61eb03243d45'),
('norma', 'Resolución SSN 551/2024 (RESOL-2024-551-APN-SSN#MEC)', null, null, null, null, null, null, null, null, '4, 5, 8 y 11', array['suma asegurada']::text[], null, 'Límites anteriores, para pólizas emitidas o renovadas desde el 1/1/2025: $16.000.000 por muerte o incapacidad total en el seguro obligatorio y $160.000.000 por acontecimiento en el voluntario para autos y motos. Útil para siniestros con pólizas de 2025.', false, 'https://www.boletinoficial.gob.ar/detalleAviso/primera/316482/20241101', null, null, 'relevamiento', '46204d9235c576618a1840beef6f424f')
